Lemma tail_tab : forall i (E E' : env) p n,
  is_tail i = true -> phase i E p -> uv E (EVar 11) = n -> 1 <= n <= 21 ->
  (needs i = 67%nat -> 1 <= uv E' (EVar 66) <= 400) -> (needs i = 67%nat -> uv E' (EVar 66) = uv E (EVar 66)) ->
  (needs i = 70%nat -> 3 <= uv E' (EVar 69) <= 24) -> (needs i = 70%nat -> uv E' (EVar 69) = uv E (EVar 69)) ->
  (F3i i = true -> 1 <= (uv E' (EVar 11) + uv E' (EVar 12)) mod 2 ^ 64 <= 17 /\ 0 <= uv E' (EVar 12) <= 16) ->
  uv E' (EVar 11) = n -> uv E' (EVar 12) = uv E (EVar 12) ->
