Lemma goto_tab : forall i j sg (E E' : env) p n,
  goto_ok i j sg = true ->
  lo i <= p <= hi i n (uv E (EVar 12)) (uv E (EVar 33)) (uv E (EVar 66)) (uv E (EVar 69)) ->
  (needs i = 67%nat -> 1 <= uv E' (EVar 66) <= 400) -> (needs i = 67%nat -> uv E' (EVar 66) = uv E (EVar 66)) ->
  (i = 37%nat -> 0 <= uv E' (EVar 33) <= 3) ->
  (i = 45%nat -> 1 <= (uv E' (EVar 11) - uv E' (EVar 33)) mod 2 ^ 64 <= 20 /\ 1 <= uv E' (EVar 33) <= 17) ->
  (F6i i = true -> 25 <= uv E' (EVar 66) <= 41 /\ 1 <= uv E' (EVar 33) <= 17) ->
  (i = 1%nat -> 1 <= uv E' (EVar 33) <= 17) ->
  uv E' (EVar 11) = n -> uv E' (EVar 12) = uv E (EVar 12) -> uv E' (EVar 33) = uv E (EVar 33) -> 1 <= n <= 21 ->
